{
  "title": "Đà Lạt chậm rãi quanh hồ",
  "summary": "Một ngày nhẹ nhàng quanh khu trung tâm, vừa đi vừa nghỉ, ăn ngon và ngắm phố về đêm.",
  "stops": [
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mở màn bằng vòng quanh hồ cho tỉnh ngủ, gió mát không cần vội.",
      "must_do_id": null
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Hoa nở rực rỡ ngay gần hồ, đi chậm để mắt kịp ngắm từng luống.",
      "must_do_id": null
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ngồi xuống ăn nem nướng đúng kiểu, vừa lạ miệng vừa ấm bụng.",
      "must_do_id": null
    },
    {
      "poi_id": "p136",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà ga cổ gần đó, ghé xem kiến trúc xưa mà không mất công đi xa.",
      "must_do_id": null
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi quán vừa cà phê vừa ăn tối, khỏi phải chạy lòng vòng.",
      "must_do_id": null
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Khu phố lên đèn ngay cạnh chỗ ăn, thả bộ chơi cho hết đêm.",
      "must_do_id": null
    }
  ]
}
